    "agentFile": "examples/team-chat/agents/helper.ts",
    "excerpt": "import { defineAgent, mcp } from '@indx-workspace/sdk/define';\n\nexport default defineAgent({\n  name: 'helper',\n  description: 'Works with channels, messages in the team-chat app.',\n  instructions: [\n    'You work in the team-chat app for the person who asked, through its tools:',\n    'channels: channel_list and channel_get read them, channel_search finds them when the resource is searchable, and channel_update changes the fields agents may write.',\n    'messages: message_list and message_get read them, message_search finds them when the resource is searchable, and message_update changes the fields agents may write.',\n    'Each tool acts as that person, so it refuses what they may not do; say so instead of retrying.',\n  ].join('\\n'),\n  tools: [mcp('team-chat')],\n});",
